#define DELAY 1.231
#define LOOP 4.333-DELAY

#define ALIAS 0.003

vec4 aaTexture(sampler2D s, vec2 uv) {
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        return vec4(0.0);
    }

    float d = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    vec4 tex = texture(s, uv);
    if (d < ALIAS) {
        float alpha = smoothstep(0.0, ALIAS, d);
        return mix(tex, vec4(0.0), 1.0 - alpha);
    }

    return tex;
}

// From https://github.com/Visual-Vincent/Lens-Correction-GLSL/blob/master/Fisheye1.frag
vec2 lensDistort(vec2 uv, float ammount) {
    float uva = atan(uv.x, uv.y);
    float uvd = sqrt(dot(uv, uv));
    uvd = uvd * (1.0 + ammount * uvd * uvd);
    return vec2(0.5) + vec2(sin(uva), cos(uva)) * uvd;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy / iResolution.xy) - vec2(0.5);

    float time = pow(max(mod(iTime, LOOP)-DELAY, 0.0), 3.);
    float o = dFdx(sin(uv.x*2.)*(0.1/time)/abs(uv.y*3.0));

    vec4 tex = aaTexture(iChannel0, lensDistort(uv, max(10000.0/abs(o), 0.5)));

    o = time == 0.0 ? 1.0:o;
    fragColor = vec4(mix(vec3(0.0), tex.xyz, min(o, 2.0)), 1.0);
    //fragColor = vec4(mix(vec3(0.0), tex.xyz, 1.0), 1.0);
}
